def line_circle(kind,y):
    p={'O':(50,32),'R':(70,32),'_U':(12,y),'_V':(88,y)}
    init=v(['O'],lines=[['_U','_V']],circles=[circle('O','R')])
    out=deepcopy(init);checks=[]
    if kind=='secant':
        d=math.sqrt(400-(y-32)**2);p['A']=(50-d,y);p['B']=(50+d,y);out['points'] += ['A','B'];checks=[equal(('O','R'),('O','A'),('O','B'))]
        rows=[s('Когда прямую называют секущей?','Если у прямой и окружности две общие точки A и B, прямую называют секущей. Отрезок AB между ними — хорда.','Определение секущей',[42])];title='Секущая: две общие точки'
    elif kind=='tangent':
        p['A']=(50,y);out['points'].append('A');checks=[equal(('O','R'),('O','A'))]
        rows=[s('Что называют касательной и точкой касания?','Касательная имеет с окружностью ровно одну общую точку A. Эту единственную общую точку называют точкой касания.','Определения',[42])];title='Касательная: одна общая точка'
    else:
        rows=[s('Как выглядит третий случай?','Прямая может совсем не иметь общих точек с окружностью. Это отдельный случай, её нельзя называть ни секущей, ни касательной.','Число общих точек',[42])];title='Нет общих точек'
    return piece(title,rows,p,init,[out],checks,offsets={'O':[0,-6],'A':[-5,5],'B':[5,5]})
