# General distance proof works on either side of the axis, but each position is a separate scene.
def distance_piece(title,A,B):
    p={'A':A,'B':B,'A1':(100-A[0],A[1]),'B1':(100-B[0],B[1]),'F':(50,A[1]),'E':(50,B[1]),'_U':(50,7),'_V':(50,63)}
    z0=v(['A','B','A1','B1'],[['A','B'],['A1','B1']],lines=[['_U','_V']])
    z1=v(['A','B','A1','B1','F','E'],[['A','B'],['A1','B1'],['A','A1'],['B','B1']],lines=[['_U','_V']],equalSegments=[eq('A','F'),eq('F','A1'),eq('B','E',2),eq('E','B1',2)],rightAngles=[rt('A','F','E'),rt('B','E','F')])
    z2=deepcopy(z1);z2['segments'] += [['F','B'],['F','B1']];z2['equalSegments']=[eq('A','F'),eq('F','A1'),eq('F','B',2),eq('F','B1',2)]
    z3=deepcopy(z2);z3['angleArcs']=[ar('F','A','B',1),ar('F','A1','B1',1)]
    z4=deepcopy(z0);z4['equalSegments']=[eq('A','B'),eq('A1','B1')]
    rows=[s('Какие вспомогательные точки нужны?','Пусть A ↔ A₁ и B ↔ B₁. Обозначим основания перпендикуляров к оси F и E. Пока рассматриваем случай F ≠ E и обе исходные точки вне оси. Тогда AF = FA₁, BE = EB₁.','Определение симметричных точек',[44]),
          s('Почему FB = FB₁?','Соединим F с B и B₁. Точка F лежит на серединном перпендикуляре к BB₁, поэтому FB = FB₁. Треугольник BFB₁ равнобедренный; его медиана FE является биссектрисой.','Серединный перпендикуляр и свойство медианы',[18,40]),
          s('Какие углы нужны для первого признака?','Равные углы между FE и FB, FB₁ дают ∠AFB = ∠A₁FB₁: эти углы получаются из прямых углов прибавлением или вычитанием одинакового угла. Это верно как для одной, так и для разных сторон оси.','Сложение и вычитание равных углов',[9]),
          s('Почему расстояния сохраняются?','В AFB и A₁FB₁ равны AF = A₁F, FB = FB₁ и углы между ними. По первому признаку треугольники равны, поэтому AB = A₁B₁.','Первый признак равенства',[15])]
    return piece(title,rows,p,z0,[z1,z2,z3,z4],[equal(('A','F'),('A1','F')),equal(('B','E'),('B1','E')),equal(('F','B'),('F','B1')),equal(('A','B'),('A1','B1')),perp('A','A1','_U','_V')],offsets={'A':[-5,5],'A1':[5,5],'B':[-5,-5] if B[0]<50 else [5,-5],'B1':[5,-5] if B[0]<50 else [-5,-5],'F':[5,5],'E':[5,-5]})
