COMPASS_ONLY=piece('Только циркуль',[
 s('Какие центры можно выбрать на готовой прямой?','Если M на b, её образ — M. Иначе отметьте на уже данной прямой b две разные точки P и Q. Новые прямые в этом способе проводить не нужно.','Условие построения одним циркулем',[44]),
 s('Какие две окружности провести?','Циркулем начертите окружность с центром P через M и окружность с центром Q через M. Их радиусы PM и QM могут быть разными.','Определение окружности',[21]),
 s('Как выбрать нужное пересечение?','Кроме общей точки M у этих окружностей есть вторая общая точка M₁ с другой стороны b. Она существует: симметричная M точка равноудалена с M от P и Q, лежащих на оси, а значит, принадлежит обеим окружностям.','Существование образа и свойство серединного перпендикуляра',[40,45]),
 s('Почему M₁ действительно симметрична M?','PM = PM₁ и QM = QM₁ как радиусы. Поэтому P и Q лежат на серединном перпендикуляре к MM₁; через них проходит именно данная прямая b. Следовательно, b — ось пары. Чертёж на бумаге и соблюдение запрета на линейку проверяются вручную.','Обратное свойство серединного перпендикуляра',[40,44])],cmp,cm0,[cm1,cm2,cm3,cm3],[equal(('P','M'),('P','M1')),equal(('Q','M'),('Q','M1')),perp('M','M1','P','Q')],offsets={'M':[0,6],'M1':[0,-6],'P':[-5,-5],'Q':[5,-5]})
def cut(p,indices,title=None):
    q=deepcopy(p);q['rows']=[deepcopy(p['rows'][i]) for i in indices];q['views']=[deepcopy(p['views'][i]) for i in indices];q['cases']=[]
    if title:q['title']=title
    return q

def question(n,title,statement,answer,*pieces):
    add('selfcheck',n,title,[112 if n<=5 else 113 if n<=26 else 114],statement,answer,*pieces)

question(1,'Геометрическое место точек','Что называют геометрическим местом точек? Приведите примеры.',
 'Множество всех точек с данным свойством. Примеры: окружность заданного радиуса и центра; параллельная на заданном расстоянии в одной полуплоскости; серединный перпендикуляр; внутренняя биссектриса без вершины.',LOCUS)
question(2,'Свойство биссектрисы и обратное','Сформулируйте и докажите теорему о биссектрисе угла в обоих направлениях.',
 'Точка биссектрисы равноудалена от прямых сторон. Обратно, внутренняя равноудалённая точка лежит на биссектрисе. Прямоугольные треугольники сравнивают по гипотенузе и углу либо по гипотенузе и катету.',BIS_DIRECT,BIS_BACK)
question(3,'Пересечение биссектрис','Докажите, что три биссектрисы треугольника пересекаются в одной точке.',
 'Пересечение первых двух биссектрис равноудалено от всех сторон, поэтому по обратному свойству принадлежит третьей.',BIS_CONC)
question(4,'Определение серединного перпендикуляра','Какую прямую называют серединным перпендикуляром к отрезку?',
 'Прямую через середину отрезка, перпендикулярную ему.',PB_DEF)
question(5,'Свойство серединного перпендикуляра','Сформулируйте и докажите теорему о серединном перпендикуляре в обоих направлениях.',
 'Все и только точки серединного перпендикуляра равноудалены от концов отрезка. Случай самой середины включается.',PB_DIRECT,PB_BACK)
question(6,'Три серединных перпендикуляра','Докажите пересечение серединных перпендикуляров к сторонам треугольника в одной точке.',
 'Пересечение первых двух равноудалено от всех трёх вершин и потому принадлежит третьему.',PB_CONC)
question(7,'Окружность, хорда, диаметр','Определите окружность с центром O и радиусом r, хорду и диаметр окружности.',
 'Окружность: OX = r > 0. Хорда соединяет две её точки; диаметр — хорда через центр, его длина 2r.',cut(CIRCLE_DEF,[0,1]))
question(8,'Свойства диаметра','Сформулируйте и докажите свойства диаметра окружности: связь с серединой и перпендикуляром к хорде, а также связь с прямым углом.',
 'Для хорды, не являющейся диаметром: диаметр через её середину перпендикулярен ей. Обратно, перпендикулярный диаметр делит любую хорду пополам. Точка видит AB под прямым углом тогда и только тогда, когда лежит на окружности с диаметром AB и отлична от A, B.',CHORD_DIRECT,CHORD_BOUNDARY,CHORD_BACK,RIGHT_TO_CIRCLE,CIRCLE_TO_RIGHT)
question(9,'Диаметр виден под прямым углом','Что означает: диаметр AB виден из точки C под прямым углом?',
 'Это означает ∠ACB = 90°; C отличается от A и B.',cut(RIGHT_TO_CIRCLE,[0]))
question(10,'Число пересечений','Может ли прямая иметь с окружностью больше двух общих точек? Обоснуйте.',
 'Нет: центр должен был бы лежать на двух различных параллельных серединных перпендикулярах к отрезкам одной прямой.',AT_MOST_TWO)
question(11,'Секущая','Какая прямая является секущей по отношению к окружности?',
 'Прямая с двумя общими точками с окружностью.',SECANT)
question(12,'Касательная и точка касания','Определите касательную к окружности и точку касания.',
 'Касательная имеет ровно одну общую точку с окружностью; она называется точкой касания.',TANGENT_DEF)
question(13,'Свойство касательной','Сформулируйте и докажите теорему о свойстве касательной.',
 'Касательная перпендикулярна радиусу к точке касания. Наклонный радиус привёл бы к существованию второй общей точки.',TANGENT_PROP)
question(14,'Два отрезка касательных','Что известно об отрезках касательных к окружности из одной точки? Обоснуйте оба свойства.',
 'Отрезки равны и образуют равные углы с прямой через данную точку и центр. Доказательство — равенство прямоугольных треугольников по гипотенузе и радиусу-катету.',TWO_TANGENTS)
question(15,'Признак касательной','Сформулируйте и докажите утверждение, обратное свойству касательной.',
 'Прямая через точку окружности, перпендикулярная радиусу в этой точке, — касательная. Все остальные точки прямой дальше от центра, чем радиус.',TANGENT_CRIT)
question(16,'Построение касательной','Как через данную точку окружности провести касательную?',
 'Провести радиус и построить в его конце на окружности перпендикуляр. По признаку это единственная касательная.',TANGENT_BUILD)
question(17,'Касательный отрезок и луч','Какой отрезок или луч называют касательным к окружности?',
 'Он лежит на касательной прямой и содержит точку касания. Принадлежности одной только прямой недостаточно.',TANGENT_PART)
question(18,'Окружности в угле','Что означает окружность, вписанная в неразвёрнутый угол? Сколько их и где находятся центры?',
 'Она касается обеих сторон-лучей. Таких окружностей бесконечно много; их центры — все точки внутренней биссектрисы, кроме вершины.',IN_ANGLE)
question(19,'Вписанная окружность треугольника','Какая окружность называется вписанной в треугольник? Какой треугольник называется описанным около окружности?',
 'Если все три стороны треугольника касаются окружности, она вписанная, а треугольник описанный около неё.',IN_DEF)
question(20,'Существование и единственность вписанной окружности','Сформулируйте и докажите теорему о вписанной окружности треугольника. Сколько таких окружностей у данного треугольника?',
 'В любой треугольник можно вписать ровно одну окружность: центр в пересечении внутренних биссектрис, радиус равен расстоянию до стороны.',INCIRCLE)
question(21,'Описанная окружность треугольника','Какая окружность называется описанной около треугольника? Какой треугольник называется вписанным в окружность?',
 'Если все вершины треугольника лежат на окружности, она описанная, а треугольник вписанный в неё.',OUT_DEF)
question(22,'Существование и единственность описанной окружности','Сформулируйте и докажите теорему об описанной окружности. Сколько окружностей можно описать около данного треугольника?',
 'Около любого треугольника можно описать ровно одну окружность: центр в пересечении серединных перпендикуляров, радиус равен расстоянию до вершины.',CIRCUMCIRCLE)
question(23,'Симметричные точки','Какие две точки называют симметричными относительно прямой?',
 'Для разных точек прямая является серединным перпендикуляром к соединяющему их отрезку. Каждая точка самой прямой симметрична себе.',POINT_SYM)
question(24,'Симметричная фигура','Какую фигуру называют симметричной относительно прямой?',
 'Фигуру, которая вместе с каждой своей точкой содержит симметричную ей точку. Прямая — её ось симметрии.',FIGURE_SYM)
question(25,'Две симметричные фигуры','Какие две фигуры симметричны относительно прямой?',
 'Каждая точка одной симметрична некоторой точке другой, и наоборот; проверяются все точки обеих фигур.',PAIR_SYM)
question(26,'Образ точки относительно оси','Как построить точку, симметричную данной относительно заданной оси?',
 'Для точки вне оси опустить перпендикуляр, продолжить его за основание и отложить равную длину. Точка оси остаётся на месте.',POINT_BUILD)
question(27,'Ось двух точек','Как построить ось симметрии двух данных точек?',
 'Для разных точек построить их серединный перпендикуляр с помощью двух равных окружностей. Для совпавших точек подходит любая прямая через них.',AXIS_BUILD)
question(28,'Пересечение симметричных прямых с осью','Может ли только одна из двух симметричных прямых пересекать ось? Объясните ответ.',
 'Нет: точка оси неподвижна и должна принадлежать обеим прямым. Для разных прямых их пересечение находится на оси; отдельно возможны параллельность и совпадение.',LINES_MEET,LINES_PAR,LINES_SAME)
question(29,'Сохранение расстояний','Равны ли AB и A₁B₁, если A₁ и B₁ симметричны A и B относительно прямой? Обоснуйте во всех расположениях.',
 'Да, AB = A₁B₁. Общий случай следует из первого признака равенства; один общий перпендикуляр — из сумм или разностей отрезков; точки оси неподвижны.',DIST_SAME_SIDE,DIST_OPPOSITE,DIST_PARALLEL,DIST_ONE_FOOT,DIST_ONE_FOOT_OPP,DIST_ON_AXIS)
question(30,'Два способа построить симметричную точку','Постройте образ M относительно прямой b: а) циркулем и линейкой; б) только циркулем. Объясните оба построения.',
 'а) Через основание перпендикуляра перенести длину на противоположную сторону. б) Выбрать два центра на данной прямой, провести окружности через M и взять их вторую общую точку. Если M на b, ответ в обоих способах — сама M.',RULER_BUILD,COMPASS_ONLY)

def main():
    assert [r['number'] for r in THEORY]==list(range(39,46))
    assert [r['number'] for r in QUESTIONS]==list(range(1,31))
    prep=dict(schemaVersion=1,bookId='atanasyan-2023-7-9',chapter=5,theory=THEORY,selfchecks=QUESTIONS,
              source=dict(printedPages=[91,114],pdfPages=[92,115],sha256=SHA),
              status='Author-verified draft; independent review and chapter-specific release manifest required.')
    for path,data in [(DEST/'preparation/chapter-05-theory.json',prep),
                      (DEST/'models/chapter-05-theory.json',dict(schemaVersion=1,bookId='atanasyan-2023-7-9',chapter=5,models=MODELS))]:
        path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(theory=len(THEORY),selfchecks=len(QUESTIONS),models=len(MODELS),
                         steps=sum(len(r['steps']) for r in THEORY+QUESTIONS),
                         views=sum(len(m['model']['views']) for m in MODELS),
                         claims=sum(len(m['model']['checks']) for m in MODELS)),ensure_ascii=False))

if __name__=='__main__': main()
